#include "BMP.h"#include "FileStuff.h"//----------------------------------------------------------------------------------------		char scanlinePad[7] = { 0, 0, 0, 0, 0, 0, 0 }, filePad[7] = { 0, 0, 0, 0, 0, 0, 0 };//----------------------------------------------------------------------------------------	long SwapEndian ( long );//----------------------------------------------------------------------------------------	OSErr writeBMP ( Str255 thePictureFileName, long theWidth, long theHeight, Myth256Palette *thePalette, char *theBits ){	FSSpec		thePictureFileFSSpec;	short		thePictureFileRef;	OSErr		theError; 	char scanlinePad[4] = { 0, 0, 0, 0 }; 	long theSize, theBitMapSize, thePadLength;	int i;		picturePalette	thePicturePalette[256];	tagBITMAPFILEHEADER	bitmapHeader;	tagBITMAPINFOHEADER	bitmapInfoHeader;	//----------------------------------------------------------------------------------------		theSize = theWidth * theHeight;	thePadLength = 4 - (theWidth % 4);		// BMPs have to have a scanline divisible by 4	if ( thePadLength == 4 )		thePadLength = 0;	theBitMapSize = (theWidth + thePadLength) * theHeight;	HCreate ( 0L, 0L, thePictureFileName, 'ogle', 'BMPf' );	theError = FSMakeFSSpec (0L, 0L, thePictureFileName, &thePictureFileFSSpec);	theError = FSpOpenDF ( &thePictureFileFSSpec, fsCurPerm, &thePictureFileRef );	if ( theError != noErr )		return theError;	bitmapHeader.bfType = 0x424D;	bitmapHeader.bfSize = SwapEndian ( theBitMapSize + 1078L );	bitmapHeader.bfReserved1 = 0x0;	bitmapHeader.bfReserved2 = 0x0;	bitmapHeader.bfOffBits = SwapEndian ( 1078L );// in the next 5 lines I'm writing each flag out individually due to a structure alignment problem// or something else which was causing garbage to go into the bitmap header// since this worked I never got around figuring out what caused the problem	FileWrite ( &bitmapHeader.bfType, sizeof(short), thePictureFileRef);	FileWrite ( &bitmapHeader.bfSize, sizeof(long), thePictureFileRef);	FileWrite ( &bitmapHeader.bfReserved1, sizeof(short), thePictureFileRef);	FileWrite ( &bitmapHeader.bfReserved2, sizeof(short), thePictureFileRef);	FileWrite ( &bitmapHeader.bfOffBits, sizeof(long), thePictureFileRef);	bitmapInfoHeader.biSize = 0x28000000;	bitmapInfoHeader.biWidth = SwapEndian ( theWidth );	bitmapInfoHeader.biHeight = SwapEndian ( theHeight );	bitmapInfoHeader.biPlanes = 0x0100;	bitmapInfoHeader.biBitCount = 0x0800;	bitmapInfoHeader.biCompression = 0;	bitmapInfoHeader.biSizeImage = 0;	bitmapInfoHeader.biXPelsPerMeter = 0x00000B12;	bitmapInfoHeader.biYPelsPerMeter = 0x00000B12;	bitmapInfoHeader.biClrUsed = 0;	bitmapInfoHeader.biClrImportant = 0;	FileWrite ( &bitmapInfoHeader, 40, thePictureFileRef );		for (i = 0; i < 256; i++){		thePicturePalette[i].rsvd = 0;		thePicturePalette[i].blue = thePalette->color[i].blue;		thePicturePalette[i].green = thePalette->color[i].green;		thePicturePalette[i].red = thePalette->color[i].red;	}	FileWrite ( thePicturePalette, sizeof(picturePalette) * 256, thePictureFileRef );	for(i = theSize - theWidth; i >= 0; i -= theWidth){		FileWrite ( &theBits[i], theWidth, thePictureFileRef );		FileWrite ( scanlinePad, thePadLength, thePictureFileRef );	}	FSClose ( thePictureFileRef );	return noErr;}